<template><div class="page"><el-card><template #header><span>文件管理</span></template><el-table :data="list" border><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="name" label="文件名"/><el-table-column prop="category" label="分类" width="100"/><el-table-column prop="size" label="大小" width="100"/><el-table-column prop="mime_type" label="类型" width="120"/><el-table-column prop="created_at" label="上传时间" width="170"/><el-table-column label="操作" width="150"><template #default="{row}"><el-button size="small" @click="preview(row)">预览</el-button><el-button size="small" type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" v-model:page-size="limit" :total="total" @current-change="loadList" style="margin-top:15px;justify-content:flex-end"/></el-card><el-dialog v-model="showPreview" title="文件预览" width="600px"><el-image v-if="previewFile && previewFile.mime_type && previewFile.mime_type.startsWith('image')" :src="previewFile.url" fit="contain" style="max-height:400px"/><div v-else-if="previewFile"><p>文件名：{{previewFile.name}}</p><p>大小：{{previewFile.size}} bytes</p><p>类型：{{previewFile.mime_type}}</p><p>路径：{{previewFile.path}}</p></div></el-dialog></div></template><script setup>import{ref,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import request from'@/utils/request';const list=ref([]);const total=ref(0);const page=ref(1);const limit=ref(20);const showPreview=ref(false);const previewFile=ref(null);const loadList=async()=>{const res=await request({url:'/file-managers',params:{page:page.value,limit:limit.value}});list.value=res.data?.list||[];total.value=res.data?.total||0};const preview=(row)=>{previewFile.value=row;showPreview.value=true};const remove=async(row)=>{await ElMessageBox.confirm('确定删除？','提示',{type:'warning'});await request({url:`/file-managers/${row.id}`,method:'delete'});ElMessage.success('删除成功');loadList()};onMounted(()=>loadList())</script>
